import { parseBoardCode } from './deck.ts';
import { activateCard, advanceGame, createGame } from './game.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  isWithinBytes,
  parseJson,
} from './saved-format.ts';
import type { GameState } from './game.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_MAX_BYTES = 1_048_576;
export const REPLAY_MAX_ACTIONS = 10_000;
const REPLAY_KEYS = ['version', 'boardCode', 'actions', 'endMs'];
const ACTION_KEYS = ['atMs', 'index'];

export const ReplayProblem = {
  tooLarge: 'tooLarge',
  malformedJson: 'malformedJson',
  format: 'format',
  boardCode: 'boardCode',
  actions: 'actions',
  endTime: 'endTime',
  action: 'action',
  order: 'order',
  index: 'index',
} as const;
export type ReplayProblemKind = (typeof ReplayProblem)[keyof typeof ReplayProblem];
type ReplayResult =
  { readonly state: GameState } | { readonly problem: ReplayProblemKind; readonly action?: number };

export function readReplay(text: string): ReplayResult {
  if (!isWithinBytes(text, REPLAY_MAX_BYTES)) return { problem: ReplayProblem.tooLarge };
  const value = parseJson(text);
  if (value === undefined) return { problem: ReplayProblem.malformedJson };
  if (!isJsonObject(value) || !hasExactKeys(value, REPLAY_KEYS) || value.version !== REPLAY_VERSION)
    return { problem: ReplayProblem.format };
  if (typeof value.boardCode !== 'string' || !parseBoardCode(value.boardCode))
    return { problem: ReplayProblem.boardCode };
  if (!Array.isArray(value.actions) || value.actions.length > REPLAY_MAX_ACTIONS)
    return { problem: ReplayProblem.actions };
  if (!isNonnegativeSafeInteger(value.endMs)) return { problem: ReplayProblem.endTime };
  let state = createGame(value.boardCode);
  let previousTime = 0;
  for (const [position, action] of value.actions.entries()) {
    if (
      !isJsonObject(action) ||
      !hasExactKeys(action, ACTION_KEYS) ||
      !isNonnegativeSafeInteger(action.atMs) ||
      !isNonnegativeSafeInteger(action.index)
    )
      return { problem: ReplayProblem.action, action: position };
    if (action.atMs < previousTime || action.atMs > value.endMs)
      return { problem: ReplayProblem.order, action: position };
    if (action.index >= state.deck.length)
      return { problem: ReplayProblem.index, action: position };
    state = activateCard(advanceGame(state, action.atMs - previousTime), action.index);
    previousTime = action.atMs;
  }
  return { state: advanceGame(state, value.endMs - previousTime) };
}

export function replayGame(text: string): GameState | null {
  const result = readReplay(text);
  return 'state' in result ? result.state : null;
}

import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
export const CLOCK_INTERVAL_MS = 40;

interface ActiveClock {
  readonly observedAt: number;
}

export function createClock(now: number): ActiveClock {
  return { observedAt: now };
}

// Fractions stay in the game, so a mismatch runs from its own activation and only exports round.
export function elapsedStep(clock: ActiveClock, now: number, active: boolean) {
  const delta = now - clock.observedAt;
  const milliseconds = active && Number.isFinite(delta) && delta > 0 ? delta : 0;
  return { clock: createClock(now), milliseconds };
}
